import{c as t,Z as i,Q as e,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"青玉案·元夕","description":"","frontmatter":{"title":"青玉案·元夕","author":"辛弃疾","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/7.md","filePath":"books/shici/songci/7.md"}'),s={name:"books/shici/songci/7.md"};function h(u,a,c,p,q,d){const o=i("PoemNav");return e(),l("div",null,[a[0]||(a[0]=r('<h1 id="青玉案·元夕" tabindex="-1">青玉案·元夕 <a class="header-anchor" href="#青玉案·元夕" aria-label="Permalink to &quot;青玉案·元夕&quot;">​</a></h1><p><strong>[宋] <a href="/authors/xinqiji.html">辛弃疾</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>东风夜放花千树，更吹落、星如雨。宝马雕车香满路。凤箫声动，玉壶光转，一夜鱼龙舞。</p><p>蛾儿雪柳黄金缕，笑语盈盈暗香去。众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>青玉案：词牌名</li><li>元夕：农历正月十五元宵节</li><li>花千树：形容花灯之多，如千树花开</li><li>星如雨：形容焰火纷纷，乱落如雨</li><li>宝马雕车：装饰华贵的车马</li><li>凤箫：箫的美称</li><li>玉壶：比喻明月</li><li>鱼龙舞：指鱼灯、龙灯各样灯彩舞动</li><li>蛾儿雪柳黄金缕：宋代女子元宵节佩戴的头饰</li><li>盈盈：形容女子仪态美好</li><li>暗香：指女子身上的香气</li><li>千百度：千百次</li><li>蓦然：突然</li><li>阑珊：零落稀疏</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>东风吹开了元宵夜的火树银花，焰火纷纷飘落如雨。豪华的马车满路芳香。悠扬的凤箫声四处回荡，明月渐渐西斜，鱼灯龙灯整夜飞舞。</p><p>美人头上戴着蛾儿、雪柳、黄金缕等头饰，笑语盈盈地走过，身上散发着淡淡的香气。我在人群中寻找她千百次，忽然回头，却发现她独自站在灯火稀疏的地方。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是辛弃疾的代表作，描写了元宵节的热闹景象和词人在人群中寻找心上人的情景，是宋词中的千古名篇。</p><p>上片写元宵节的热闹景象。&quot;东风夜放花千树，更吹落、星如雨&quot;，以夸张的手法写花灯和焰火的盛况，将元宵之夜描绘得如梦如幻。&quot;宝马雕车香满路&quot;写游人如织、车马喧嚣的繁华景象。&quot;凤箫声动，玉壶光转，一夜鱼龙舞&quot;，从听觉、视觉角度写节日的欢乐气氛。</p><p>下片写寻觅心上人的情景。&quot;蛾儿雪柳黄金缕，笑语盈盈暗香去&quot;，写游女们盛装出游的热闹场面。&quot;众里寻他千百度&quot;，写词人苦苦寻觅的心情。&quot;蓦然回首，那人却在，灯火阑珊处&quot;，是全词的点睛之笔。词人在热闹的人群中寻觅不得，却在灯火稀疏之处发现了她。这里的&quot;那人&quot;，既是词人心中的理想人物，也可以理解为词人自己的精神寄托——不随波逐流、保持独立品格的象征。</p><p>全词构思巧妙，意境深远，将热闹的场景与孤独的情怀形成鲜明对比，体现了辛弃疾词作豪放与婉约兼备的特色。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>辛弃疾</strong>（1140年－1207年），字幼安，号稼轩，南宋豪放派词人代表，与苏轼并称&quot;苏辛&quot;。其词风格多样，既有豪放激昂之作，也有婉约细腻之篇。</p><p><a href="/authors/xinqiji.html">查看作者详情 →</a></p></blockquote>',18)),n(o)])}const b=t(s,[["render",h]]);export{m as __pageData,b as default};
